#!/bin/bash -x

# Vala Generation Comparison Test
# Compares Vala files generated by /usr/bin/roobuilder vs local build
# Tests single BJS file first, then can be extended to batch testing

set -e

# Configuration
SYSTEM_ROOBUILDER="/usr/bin/roobuilder"
LOCAL_ROOBUILDER="./build/roobuilder"
ROOBUILDER_PROJECT="/home/alan/gitlive/roobuilder"
TEST_DIR="/tmp/vala_comparison_test_$(date +%Y%m%d_%H%M%S)"
LOG_FILE="$TEST_DIR/test_results.log"
DIFF_FILE="$TEST_DIR/differences.log"

# Results directory for failed tests (only created if there are differences)
RESULTS_DIR="tests/results"

# Colors for output
RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
BLUE='\033[0;34m'
NC='\033[0m' # No Color

# Create test directory
mkdir -p "$TEST_DIR"
echo "Test directory created: $TEST_DIR"

# Logging function
log() {
    echo -e "$1" | tee -a "$LOG_FILE"
}

# Error handling
handle_error() {
    log "${RED}ERROR: $1${NC}"
    log "${RED}Test failed at line $2${NC}"
    exit 1
}

# Clean output function (removes file structure dumps)
clean_output() {
    local input_file="$1"
    local output_file="$2"
    
    # Remove lines that start with "File /" (file structure dumps)
    # Keep only lines starting with "static" or later (actual code)
    sed -n '/^static/,$p' "$input_file" > "$output_file"
    
    # If no "static" found, try other patterns
    if [ ! -s "$output_file" ]; then
        # Try to find the actual start of the code
        sed -n '/^[a-zA-Z]/,$p' "$input_file" > "$output_file"
    fi
    
    # If still empty, copy the original
    if [ ! -s "$output_file" ]; then
        cp "$input_file" "$output_file"
    fi
}

# Compare Vala generation against existing Vala file
compare_vala_generation() {
    local bjs_file="$1"
    local filename=$(basename "$bjs_file" .bjs)
    local original_vala="${bjs_file%.bjs}.vala"
    
    log "${BLUE}=== Comparing Vala Generation for: $filename ===${NC}"
    log "BJS file: $bjs_file"
    log "Original Vala: $original_vala"
    
    # Check if original Vala file exists
    if [[ ! -f "$original_vala" ]]; then
        log "${RED}ERROR: Original Vala file not found: $original_vala${NC}"
        return 1
    fi
    
    # Check if local roobuilder exists
    if [[ ! -f "$ROOBUILDER_PROJECT/$LOCAL_ROOBUILDER" ]]; then
        log "${RED}ERROR: Local roobuilder not found: $ROOBUILDER_PROJECT/$LOCAL_ROOBUILDER${NC}"
        log "Run: ninja -C build"
        return 1
    fi
    
    # Convert to relative path (needs to be run from project dir)
    local relative_bjs_file="${bjs_file#../}"
    
    # Step 1: Generate Vala with local build and compare to original
    log "Step 1: Generating Vala with local build..."
    log "  Using relative path: $relative_bjs_file"
    log "  Running from project directory: $ROOBUILDER_PROJECT"
    
    local local_output="$TEST_DIR/${filename}_local.vala"
    local local_clean="$TEST_DIR/${filename}_local_clean.vala"
    local local_debug="$TEST_DIR/${filename}_local.log"
    
    if (cd "$ROOBUILDER_PROJECT" && timeout 30 "$LOCAL_ROOBUILDER" --project "$ROOBUILDER_PROJECT" --test-symbol-target roobuilder --debug --test-bjs-compile "$relative_bjs_file") > "$local_output" 2> "$local_debug"; then
        log "  ${GREEN}SUCCESS: Local roobuilder completed${NC}"
        if [[ -s "$local_debug" ]]; then
            log "  ${BLUE}Debug output captured: $local_debug${NC}"
        fi
    else
        local exit_code=$?
        log "  ${RED}ERROR: Local roobuilder failed (exit code: $exit_code)${NC}"
        if [[ -s "$local_output" ]]; then
            log "  Error details:"
            head -n 10 "$local_output" | sed 's/^/    /'
        fi
        if [[ -s "$local_debug" ]]; then
            log "  Debug output:"
            head -n 10 "$local_debug" | sed 's/^/    /'
        fi
        return 1
    fi
    
    # Clean the local output
    clean_output "$local_output" "$local_clean"
    
    # Compare local build output to original Vala file
    if diff -q "$local_clean" "$original_vala" > /dev/null 2>&1; then
        log "  ${GREEN}SUCCESS: Local build matches original Vala file${NC}"
        return 0
    else
        log "  ${YELLOW}Local build differs from original Vala file${NC}"
        
        # Step 2: Generate with system roobuilder to verify original is correct
        log "Step 2: Verifying original Vala file with system roobuilder..."
        
        if [[ ! -f "$SYSTEM_ROOBUILDER" ]]; then
            log "  ${RED}ERROR: System roobuilder not found: $SYSTEM_ROOBUILDER${NC}"
            log "  ${YELLOW}Proceeding with local build vs original comparison${NC}"
        else
            local system_output="$TEST_DIR/${filename}_system.vala"
            local system_clean="$TEST_DIR/${filename}_system_clean.vala"
            
            if (cd "$ROOBUILDER_PROJECT" && timeout 30 "$SYSTEM_ROOBUILDER" --project "$ROOBUILDER_PROJECT" --test-symbol-target roobuilder --test-bjs-compile "$relative_bjs_file") > "$system_output" 2>&1; then
                log "  ${GREEN}SUCCESS: System roobuilder completed${NC}"
                
                # Clean the system output
                clean_output "$system_output" "$system_clean"
                
                # Compare system output to original Vala file
                if diff -q "$system_clean" "$original_vala" > /dev/null 2>&1; then
                    log "  ${GREEN}System roobuilder matches original Vala file${NC}"
                    log "  ${RED}ISSUE: Local build differs from original (system matches original)${NC}"
                    
                    # Save results for local build failure (only generated file)
                    save_comparison_results "$filename" "$original_vala" "$local_clean" "local_failed" "$local_debug"
                    return 1
                else
                    log "  ${RED}ERROR: System roobuilder differs from original Vala file${NC}"
                    log "  ${RED}ISSUE: Current generated file doesn't match system roobuilder output${NC}"
                    
                    # Save results for system vs original failure (only system file)
                    save_comparison_results "$filename" "$original_vala" "$system_clean" "system_failed" ""
                    return 1
                fi
            else
                local exit_code=$?
                log "  ${RED}ERROR: System roobuilder failed (exit code: $exit_code)${NC}"
                log "  ${YELLOW}Proceeding with local build vs original comparison${NC}"
            fi
        fi
        
        # Save results for local build failure (only generated file)
        save_comparison_results "$filename" "$original_vala" "$local_clean" "local_failed" "$local_debug"
        return 1
    fi
}

# Save comparison results to results directory
save_comparison_results() {
    local filename="$1"
    local original_vala="$2"
    local generated_vala="$3"
    local failure_type="$4"
    local debug_log="$5"
    
    log "  ${RED}FAILURE: Generated Vala differs from original${NC}"
    
    # Create results directory if it doesn't exist
    mkdir -p "$RESULTS_DIR"
    
    # Save files based on failure type
    if [[ "$failure_type" == "local_failed" ]]; then
        # Local build failed - only save generated file and diff
        cp "$generated_vala" "$RESULTS_DIR/${filename}_generated.vala"
        log "  ${YELLOW}Saved: ${filename}_generated.vala (local build output)${NC}"
        # Save debug log if it exists
        if [[ -n "$debug_log" && -f "$debug_log" ]]; then
            cp "$debug_log" "$RESULTS_DIR/${filename}_generated.log"
            log "  ${YELLOW}Saved: ${filename}_generated.log (local build debug output)${NC}"
        fi
    elif [[ "$failure_type" == "system_failed" ]]; then
        # System/original failed - only save system file and diff
        cp "$generated_vala" "$RESULTS_DIR/${filename}_system.vala"
        log "  ${YELLOW}Saved: ${filename}_system.vala (system roobuilder output)${NC}"
        # Save debug log if it exists
        if [[ -n "$debug_log" && -f "$debug_log" ]]; then
            cp "$debug_log" "$RESULTS_DIR/${filename}_system.log"
            log "  ${YELLOW}Saved: ${filename}_system.log (system roobuilder debug output)${NC}"
        fi
    fi
    
    # Create diff file with just the unified diff
    local diff_file="$RESULTS_DIR/${filename}.diff"
    diff -u "$original_vala" "$generated_vala" > "$diff_file" 2>&1 || true
    
    # Show first few lines of difference
    log "  First 10 lines of differences:"
    diff -u "$original_vala" "$generated_vala" | head -n 10 | sed 's/^/    /'
    
    log "  ${YELLOW}Results saved to: $RESULTS_DIR${NC}"
    log "  ${YELLOW}Files: ${filename}.diff${NC}"
}

# Main test execution
main() {
    # Check if a specific file was provided
    if [[ $# -eq 0 ]]; then
        echo "Usage: $0 <bjs_file_path>"
        echo "Example: $0 ../src/Builder4/About.bjs"
        echo ""
        echo "This test compares local build Vala generation against existing Vala files:"
        echo "  1. Generate Vala with local build"
        echo "  2. Compare to existing Vala file in original directory"
        echo "  3. If different, verify with system roobuilder"
        echo "  4. Report issues based on comparison results"
        echo ""
        echo "If differences are found, results will be saved to:"
        echo "  $RESULTS_DIR/"
        echo "  - <filename>_generated.vala (if local build failed)"
        echo "  - <filename>_system.vala (if system/original failed)"
        echo "  - <filename>.diff (unified diff)"
        exit 1
    fi
    
    local bjs_file="$1"
    
    # Validate input file
    if [[ ! -f "$bjs_file" ]]; then
        log "${RED}ERROR: BJS file not found: $bjs_file${NC}"
        exit 1
    fi
    
    local file_size=$(stat -c%s "$bjs_file" 2>/dev/null || echo "0")
    if [[ "$file_size" -eq 0 ]]; then
        log "${RED}ERROR: BJS file is empty: $bjs_file${NC}"
        exit 1
    fi
    
    log "File size: $file_size bytes"
    log "Testing: $bjs_file"
    
    # Run the comparison test
    if compare_vala_generation "$bjs_file"; then
        log "${GREEN}=== TEST PASSED ===${NC}"
        log "Generated Vala files are identical between system and local roobuilder"
exit 0
    else
        log "${RED}=== TEST FAILED ===${NC}"
        log "Generated Vala files differ between system and local roobuilder"
        log "Check differences in: $DIFF_FILE"
        exit 1
    fi
}

# Initialize test environment
log "${GREEN}=== Starting Vala Generation Comparison Test ===${NC}"
log "Test directory: $TEST_DIR"
log "Log file: $LOG_FILE"
log "Differences file: $DIFF_FILE"

# Run the main test
main "$@"
